window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-3d1f51af7b7c72b5"]={"versions": [{"id": "FIG-3d1f51af7b7c72b5", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells für VFB-Timing-Blueprints innerhalb der AUTOSAR Timing Extensions (TPS TimingExtensions). Das Diagramm definiert die strukturelle Einbettung von <code>Timing::VfbTiming</code> in die Vererbungshierarchie der AUTOSAR-ARPackage-Elemente sowie die Assoziationen zu Software-Komponententypen und Timing-Beschreibungen bzw. Timing-Constraints.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>ARPackage::ARElement</code> (Stereotyp «PackageableElement», abstrakt): Wurzel-Package-Element im AUTOSAR-Metamodell.\n</li><li><code>Timing::TimingExtension</code> (Stereotyp «Identifiable», abstrakt): Spezialisiert <code>ARPackage::ARElement</code> über eine Generalisierungsbeziehung. Besitzt drei Kompositionsbeziehungen mit Stereotyp <code>«atpVariation»</code> und Kardinalität <code>0..*</code>:\n<ul class=\"fig-list\"><li><code>+timingDescription</code> zur Klasse <code>TimingDescription</code> (Stereotyp «Identifiable»).\n</li><li><code>+timingRequirement</code> zur Klasse <code>TimingConstraint::TimingConstraint</code> (Stereotypen «Identifiable», «Traceable»).\n</li><li><code>+timingGuarantee</code> zur Klasse <code>TimingConstraint::TimingConstraint</code> (Stereotypen «Identifiable», «Traceable»).\n</li></ul>\n</li><li><code>Timing::VfbTiming</code> (Stereotypen «AtpBlueprint», «AtpBlueprintable»): Konkrete Timing-Erweiterung, die über Generalisierung von <code>Timing::TimingExtension</code> erbt. Besitzt eine gerichtete Assoziation:\n<ul class=\"fig-list\"><li><code>+component</code> mit Kardinalität <code>1</code> auf die Zielklasse <code>Components::SwComponentType</code>.\n</li></ul>\n</li><li><code>Components::SwComponentType</code> (Stereotypen «AtpBlueprint», «AtpBlueprintable», «AtpType»): Ziel der Komponenten-Assoziation zur Referenzierung des Software-Komponententyps.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Ablauf- oder Sequenzinteraktionen. Die Beziehungen definieren die Deklarationsstruktur zur Erstellung von VFB-Timing-Spezifikationen und -Blueprints für Software-Komponenten im AUTOSAR-Entwicklungsprozess.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><code>Timing::VfbTiming</code> und <code>Components::SwComponentType</code> sind als Blueprints typisiert (<code>«AtpBlueprint»</code>, <code>«AtpBlueprintable»</code>), wodurch sie als Vorlagen für konkrete Modellinstanzen dienen können.\n</li><li>Die Referenz <code>+component</code> von <code>Timing::VfbTiming</code> auf <code>Components::SwComponentType</code> ist obligatorisch (Kardinalität exakt <code>1</code>).\n</li><li>Die Kompositionen für Timing-Beschreibungen, -Anforderungen und -Garantien unterstützen AUTOSAR-Variantenbildung (<code>«atpVariation»</code>).\n</li><li>Timing-Constraints (<code>TimingConstraint::TimingConstraint</code>) sind rückverfolgbar (<code>«Traceable»</code>) und eindeutig identifizierbar (<code>«Identifiable»</code>).\n</li></ul>"}, {"id": "FIG-0e5a371254abde9c", "releases": ["R4.2.2", "R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells für VFB-Timing-Blueprints innerhalb der AUTOSAR Timing Extensions (TPS TimingExtensions). Das Diagramm definiert die strukturelle Einbettung von <code>Timing::VfbTiming</code> in die Vererbungshierarchie der AUTOSAR-ARPackage-Elemente sowie die Assoziationen zu Software-Komponententypen und Timing-Beschreibungen bzw. Timing-Constraints.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>ARPackage::ARElement</code> (Stereotyp «PackageableElement», abstrakt): Wurzel-Package-Element im AUTOSAR-Metamodell.\n</li><li><code>Timing::TimingExtension</code> (Stereotyp «Identifiable», abstrakt): Spezialisiert <code>ARPackage::ARElement</code> über eine Generalisierungsbeziehung. Besitzt drei Kompositionsbeziehungen mit kombiniertem Stereotyp <code>«atpVariation,atpSplitable»</code> und Kardinalität <code>0..*</code>:\n<ul class=\"fig-list\"><li><code>+timingDescription</code> zur Klasse <code>TimingDescription</code> (Stereotyp «Identifiable»).\n</li><li><code>+timingRequirement</code> zur Klasse <code>TimingConstraint::TimingConstraint</code> (Stereotypen «Identifiable», «Traceable»).\n</li><li><code>+timingGuarantee</code> zur Klasse <code>TimingConstraint::TimingConstraint</code> (Stereotypen «Identifiable», «Traceable»).\n</li></ul>\n</li><li><code>Timing::VfbTiming</code> (Stereotypen «AtpBlueprint», «AtpBlueprintable»): Konkrete Timing-Erweiterung, die über Generalisierung von <code>Timing::TimingExtension</code> erbt. Besitzt eine gerichtete Assoziation:\n<ul class=\"fig-list\"><li><code>+component</code> mit Kardinalität <code>1</code> auf die Zielklasse <code>Components::SwComponentType</code>.\n</li></ul>\n</li><li><code>Components::SwComponentType</code> (Stereotypen «AtpBlueprint», «AtpBlueprintable», «AtpType»): Ziel der Komponenten-Assoziation zur Referenzierung des Software-Komponententyps.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Ablauf- oder Sequenzinteraktionen. Die Beziehungen definieren die Deklarationsstruktur zur Erstellung von VFB-Timing-Spezifikationen und -Blueprints für Software-Komponenten im AUTOSAR-Entwicklungsprozess.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><code>Timing::VfbTiming</code> und <code>Components::SwComponentType</code> sind als Blueprints typisiert (<code>«AtpBlueprint»</code>, <code>«AtpBlueprintable»</code>), wodurch sie als Vorlagen für konkrete Modellinstanzen dienen können.\n</li><li>Die Referenz <code>+component</code> von <code>Timing::VfbTiming</code> auf <code>Components::SwComponentType</code> ist obligatorisch (Kardinalität exakt <code>1</code>).\n</li><li>Die Kompositionen für Timing-Beschreibungen, -Anforderungen und -Garantien unterstützen Variantenbildung sowie Aufteilbarkeit über mehrere ARXML-Dateien hinweg (<code>«atpVariation,atpSplitable»</code>).\n</li><li>Timing-Constraints (<code>TimingConstraint::TimingConstraint</code>) sind rückverfolgbar (<code>«Traceable»</code>) und eindeutig identifizierbar (<code>«Identifiable»</code>).\n</li></ul>"}, {"id": "FIG-d2971e084a5f2bde", "releases": ["R18-10_R4.4.0_R1.5.0", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells für VFB-Timing-Blueprints innerhalb der AUTOSAR Timing Extensions (TPS TimingExtensions). Das Diagramm definiert die strukturelle Einbettung von <code>Timing::VfbTiming</code> in die Vererbungshierarchie der AUTOSAR-ARPackage-Elemente sowie die Assoziationen zu Software-Komponententypen und Timing-Beschreibungen bzw. Timing-Constraints.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>ARPackage::ARElement</code> (Stereotyp «PackageableElement», abstrakt): Wurzel-Package-Element im AUTOSAR-Metamodell.\n</li><li><code>Timing::TimingExtension</code> (Stereotyp «Identifiable», abstrakt): Spezialisiert <code>ARPackage::ARElement</code> über eine Generalisierungsbeziehung. Besitzt drei Kompositionsbeziehungen mit kombiniertem Stereotyp <code>«atpVariation,atpSplitable»</code> und Kardinalität <code>0..*</code>:\n<ul class=\"fig-list\"><li><code>+timingDescription</code> zur Klasse <code>TimingDescription</code> (Stereotyp «Identifiable»).\n</li><li><code>+timingRequirement</code> zur Klasse <code>TimingConstraint::TimingConstraint</code> (Stereotypen «Identifiable», «Traceable»).\n</li><li><code>+timingGuarantee</code> zur Klasse <code>TimingConstraint::TimingConstraint</code> (Stereotypen «Identifiable», «Traceable»).\n</li></ul>\n</li><li><code>Timing::VfbTiming</code> (Stereotypen «AtpBlueprint», «AtpBlueprintable»): Konkrete Timing-Erweiterung, die über Generalisierung von <code>Timing::TimingExtension</code> erbt. Besitzt eine gerichtete Assoziation:\n<ul class=\"fig-list\"><li><code>+component</code> mit Kardinalität <code>1</code> auf die Zielklasse <code>Components::SwComponentType</code>.\n</li></ul>\n</li><li><code>Components::SwComponentType</code> (Stereotypen «AtpBlueprint», «AtpBlueprintable», «AtpType»): Ziel der Komponenten-Assoziation zur Referenzierung des Software-Komponententyps.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Ablauf- oder Sequenzinteraktionen. Die Beziehungen definieren die Deklarationsstruktur zur Erstellung von VFB-Timing-Spezifikationen und -Blueprints für Software-Komponenten im AUTOSAR-Entwicklungsprozess.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><code>Timing::VfbTiming</code> und <code>Components::SwComponentType</code> sind als Blueprints typisiert (<code>«AtpBlueprint»</code>, <code>«AtpBlueprintable»</code>), wodurch sie als Vorlagen für konkrete Modellinstanzen dienen können.\n</li><li>Die Referenz <code>+component</code> von <code>Timing::VfbTiming</code> auf <code>Components::SwComponentType</code> ist obligatorisch (Kardinalität exakt <code>1</code>).\n</li><li>Die Kompositionen für Timing-Beschreibungen, -Anforderungen und -Garantien unterstützen Variantenbildung sowie Aufteilbarkeit über mehrere ARXML-Dateien hinweg (<code>«atpVariation,atpSplitable»</code>).\n</li><li>Timing-Constraints (<code>TimingConstraint::TimingConstraint</code>) sind rückverfolgbar (<code>«Traceable»</code>) und eindeutig identifizierbar (<code>«Identifiable»</code>).\n</li></ul>"}, {"id": "FIG-36c092bea9e71b61", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells für VFB-Timing-Blueprints innerhalb der AUTOSAR Timing Extensions (TPS TimingExtensions). Das Diagramm definiert die strukturelle Einbettung von <code>Timing::VfbTiming</code> in die Vererbungshierarchie der AUTOSAR-ARPackage-Elemente sowie die Assoziationen zu Software-Komponententypen und Timing-Beschreibungen bzw. Timing-Constraints.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>ARPackage::ARElement</code> (Stereotyp «PackageableElement», abstrakt): Wurzel-Package-Element im AUTOSAR-Metamodell.\n</li><li><code>Timing::TimingExtension</code> (Stereotyp «Identifiable», abstrakt): Spezialisiert <code>ARPackage::ARElement</code> über eine Generalisierungsbeziehung. Besitzt drei Kompositionsbeziehungen mit kombiniertem Stereotyp <code>«atpVariation,atpSplitable»</code> und Kardinalität <code>0..*</code>:\n<ul class=\"fig-list\"><li><code>+timingDescription</code> zur Klasse <code>TimingDescription</code> (Stereotyp «Identifiable»).\n</li><li><code>+timingRequirement</code> zur Klasse <code>TimingConstraint::TimingConstraint</code> (Stereotypen «Identifiable», «Traceable»).\n</li><li><code>+timingGuarantee</code> zur Klasse <code>TimingConstraint::TimingConstraint</code> (Stereotypen «Identifiable», «Traceable»).\n</li></ul>\n</li><li><code>Timing::VfbTiming</code> (Stereotypen «AtpBlueprint», «AtpBlueprintable»): Konkrete Timing-Erweiterung, die über Generalisierung von <code>Timing::TimingExtension</code> erbt. Besitzt eine gerichtete Assoziation:\n<ul class=\"fig-list\"><li><code>+component</code> mit Kardinalität <code>1</code> auf die Zielklasse <code>Components::SwComponentType</code>.\n</li></ul>\n</li><li><code>Components::SwComponentType</code> (Stereotypen «AtpBlueprint», «AtpBlueprintable», «AtpType»): Ziel der Komponenten-Assoziation zur Referenzierung des Software-Komponententyps.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Ablauf- oder Sequenzinteraktionen. Die Beziehungen definieren die Deklarationsstruktur zur Erstellung von VFB-Timing-Spezifikationen und -Blueprints für Software-Komponenten im AUTOSAR-Entwicklungsprozess.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><code>Timing::VfbTiming</code> und <code>Components::SwComponentType</code> sind als Blueprints typisiert (<code>«AtpBlueprint»</code>, <code>«AtpBlueprintable»</code>), wodurch sie als Vorlagen für konkrete Modellinstanzen dienen können.\n</li><li>Die Referenz <code>+component</code> von <code>Timing::VfbTiming</code> auf <code>Components::SwComponentType</code> ist obligatorisch (Kardinalität exakt <code>1</code>).\n</li><li>Die Kompositionen für Timing-Beschreibungen, -Anforderungen und -Garantien unterstützen Variantenbildung sowie Aufteilbarkeit über mehrere ARXML-Dateien hinweg (<code>«atpVariation,atpSplitable»</code>).\n</li><li>Timing-Constraints (<code>TimingConstraint::TimingConstraint</code>) sind rückverfolgbar (<code>«Traceable»</code>) und eindeutig identifizierbar (<code>«Identifiable»</code>).\n</li></ul>"}, {"id": "FIG-813b9cf124943983", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells für VFB-Timing-Blueprints innerhalb der AUTOSAR Timing Extensions (TPS TimingExtensions). Das Diagramm definiert die strukturelle Einbettung von <code>VfbTiming</code> in die Vererbungshierarchie der AUTOSAR-Elemente sowie die Assoziationen zu Software-Komponententypen und Timing-Beschreibungen bzw. Timing-Constraints.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>ARElement</code> (Stereotyp «PackageableElement», abstrakt): Wurzel-Package-Element im AUTOSAR-Metamodell.\n</li><li><code>TimingExtension</code> (Stereotyp «Identifiable», abstrakt): Spezialisiert <code>ARElement</code> über eine Generalisierungsbeziehung. Besitzt drei Kompositionsbeziehungen mit Stereotyp <code>«atpVariation,atpSplitable»</code> und Kardinalität <code>0..*</code>:\n<ul class=\"fig-list\"><li><code>+timingDescription</code> zur Klasse <code>TimingDescription</code> (Stereotyp «Identifiable»).\n</li><li><code>+timingRequirement</code> zur Klasse <code>TimingConstraint</code> (Stereotypen «Identifiable», «Traceable»).\n</li><li><code>+timingGuarantee</code> zur Klasse <code>TimingConstraint</code> (Stereotypen «Identifiable», «Traceable»).\n</li></ul>\n</li><li><code>VfbTiming</code> (Stereotypen «AtpBlueprint», «AtpBlueprintable»): Konkrete Timing-Erweiterung, die über Generalisierung von <code>TimingExtension</code> erbt. Besitzt eine gerichtete Assoziation:\n<ul class=\"fig-list\"><li><code>+component</code> mit Kardinalität <code>0..1</code> auf die Zielklasse <code>SwComponentType</code>.\n</li></ul>\n</li><li><code>SwComponentType</code> (Stereotypen «AtpBlueprint», «AtpBlueprintable», «AtpType»): Ziel der Komponenten-Assoziation zur optionalen Referenzierung eines Software-Komponententyps.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Ablauf- oder Sequenzinteraktionen. Die Beziehungen definieren die Deklarationsstruktur zur Erstellung von VFB-Timing-Spezifikationen und -Blueprints für Software-Komponenten im AUTOSAR-Entwicklungsprozess.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><code>VfbTiming</code> und <code>SwComponentType</code> sind als Blueprints typisiert (<code>«AtpBlueprint»</code>, <code>«AtpBlueprintable»</code>), wodurch sie als Vorlagen für konkrete Modellinstanzen dienen können.\n</li><li>Die Referenz <code>+component</code> von <code>VfbTiming</code> auf <code>SwComponentType</code> ist optional (Kardinalität <code>0..1</code>), womit ein VFB-Timing-Blueprint auch ohne fest zugeordneten Komponententyp definiert werden kann.\n</li><li>Die Kompositionen für Timing-Beschreibungen, -Anforderungen und -Garantien unterstützen Variantenbildung sowie Aufteilbarkeit über mehrere ARXML-Dateien hinweg (<code>«atpVariation,atpSplitable»</code>).\n</li><li>Timing-Constraints (<code>TimingConstraint</code>) sind rückverfolgbar (<code>«Traceable»</code>) und eindeutig identifizierbar (<code>«Identifiable»</code>).\n</li></ul>"}], "trans": [{"from": "FIG-3d1f51af7b7c72b5", "to": "FIG-0e5a371254abde9c", "fr": "R4.1.3", "tr": "R4.2.2", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Kompositionen <code>+timingDescription</code>, <code>+timingRequirement</code> und <code>+timingGuarantee</code> an <code>Timing::TimingExtension</code>: Stereotyp um <code>atpSplitable</code> erweitert von <code>«atpVariation»</code> auf <code>«atpVariation,atpSplitable»</code>.\n</li></ul>"}, {"from": "FIG-0e5a371254abde9c", "to": "FIG-d2971e084a5f2bde", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-d2971e084a5f2bde", "to": "FIG-36c092bea9e71b61", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-36c092bea9e71b61", "to": "FIG-d2971e084a5f2bde", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-d2971e084a5f2bde", "to": "FIG-813b9cf124943983", "fr": "R20-11", "tr": "R22-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Assoziation <code>+component</code> von <code>VfbTiming</code> zu <code>SwComponentType</code>: Multiplizität zielseitig von <code>1</code> auf <code>0..1</code> gelockert.\n</li><li>Qualifizierte Paket-Präfixe in den Klassennamen entfernt: <code>ARPackage::ARElement</code> zu <code>ARElement</code>, <code>Timing::TimingExtension</code> zu <code>TimingExtension</code>, <code>Timing::VfbTiming</code> zu <code>VfbTiming</code>, <code>Components::SwComponentType</code> zu <code>SwComponentType</code> und <code>TimingConstraint::TimingConstraint</code> zu <code>TimingConstraint</code>.\n</li></ul>"}]};
